-- Seed minimal, sans comptes, joueurs, dirigeants, résultats ni statistiques fictifs.
begin;
update public.page_content set settings_json=jsonb_set(jsonb_set(settings_json,'{fr,banner,actions,1,href}',to_jsonb('/galerie?categorie='||(select id::text from public.gallery_categories where slug='matchs'))),'{ar,banner,actions,1,href}',to_jsonb('/galerie?categorie='||(select id::text from public.gallery_categories where slug='matchs'))) where page_key='equipe' and section_key='config' and settings_json#>>'{fr,banner,actions,1,href}'='/galerie?categorie=category-0';
commit;
